def sparseBalancedPairPattern {n : ℕ} (j : ℕ) (i k : Fin n) (b : Bool) : Set (Fin n → SparseObs) :=
  {ω | i < k ∧ ω i ∈ sparseTargetObservation j b ∧
    ω k ∈ sparseTargetObservation j (!b) ∧
    ∀ l : Fin n, l ≠ i → l ≠ k → ω l ∈ sparseLowObservation j}
